def _scores(scene: dict) -> list[tuple[int, str]]:
    scores = []
    for cluster in scene["clusters"]:
        cells = {tuple(cell) for cell in cluster["cells"]}
        marker = tuple(cluster["marker"])
        score = (
            _components_after_removal(cells, marker)
            if marker in cells and _component_count(cells) == 1
            else 0
        )
        scores.append((score, str(cluster["color"])))
    return scores

def analytic_gold(scene: dict) -> str:
    scores = sorted(_scores(scene), reverse=True)
    if len(scores) != 4 or scores[0][0] < 2 or scores[0][0] == scores[1][0]:
        raise ValueError("scene lacks a unique marked articulation winner")
    return scores[0][1]

def decision_from_image(image: Image.Image) -> str:
    array = np.asarray(image.convert("RGB"), dtype=np.uint8)
    if array.ndim != 3 or array.shape[0] < 128 or array.shape[1] < 128:
        raise ValueError("unexpected raster")
    gold_mask = _near(array, GOLD)
    recovered = []
    for name, rgb in PALETTE.items():
        item = _recover_candidate(array, name, _near(array, rgb), gold_mask)
        if item is not None:
            recovered.append(item)
    winners = [(score, name) for score, name in recovered if score >= 2]
    if not winners:
        raise ValueError("no intact marked articulation candidate")
    winners.sort(reverse=True)
    if len(winners) > 1 and winners[0][0] == winners[1][0]:
        raise ValueError("ambiguous marked articulation candidates")
    runner_score = max((score for score, _ in recovered if (score, _) != winners[0]), default=1)
    if winners[0][0] - runner_score < 1:
        raise ValueError("insufficient pixel runner-up margin")
    return winners[0][1]
